import {
  AlertDialog,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  Alert,
  Button,
  Field,
  FieldLabel,
  Input,
  useI18n,
} from '@gntik-ai/ui';
import { useState, type ReactNode } from 'react';
import { translatedContent } from '../translated-content';

export interface ConfirmDestructiveDialogLabels {
  confirmPrompt: (text: ReactNode) => ReactNode;
  cancel: string;
  fallbackError: string;
}

export interface ConfirmDestructiveDialogProps {
  labels?: Partial<ConfirmDestructiveDialogLabels>;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: ReactNode;
  description: ReactNode;
  /** Text that must be typed exactly to enable the confirming button. */
  confirmText?: string;
  confirmLabel: string;
  /** Runs on confirm; a returned promise shows a loading state and keeps the dialog open until it settles. */
  onConfirm?: () => void | Promise<void>;
}

/** Destructive confirmation (alertdialog) that can require typing the resource name first. */
export function ConfirmDestructiveDialog({
  labels,
  open,
  onOpenChange,
  title,
  description,
  confirmText,
  confirmLabel,
  onConfirm,
}: ConfirmDestructiveDialogProps) {
  const { t } = useI18n();
  const [typed, setTyped] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const matches = confirmText == null || typed === confirmText;

  const change = (next: boolean) => {
    if (loading) return;
    if (!next) {
      setTyped('');
      setError(null);
    }
    onOpenChange(next);
  };

  const confirm = async () => {
    if (!matches) return;
    setError(null);
    setLoading(true);
    try {
      await onConfirm?.();
      setLoading(false);
      setTyped('');
      onOpenChange(false);
    } catch (e) {
      setLoading(false);
      setError(e instanceof Error ? e.message : (labels?.fallbackError ?? t('dangerZone.fallbackError')));
    }
  };

  return (
    <AlertDialog open={open} onOpenChange={change}>
      <AlertDialogContent size="md">
        <AlertDialogHeader tone="destructive">
          <AlertDialogTitle>{title}</AlertDialogTitle>
          <AlertDialogDescription>{description}</AlertDialogDescription>
        </AlertDialogHeader>
        <form
          className="mt-5 grid gap-4"
          onSubmit={(e) => {
            e.preventDefault();
            void confirm();
          }}
        >
          {confirmText != null && (
            <Field>
              <FieldLabel>
                {labels?.confirmPrompt?.(confirmText) ??
                  translatedContent(t('dangerZone.confirmPrompt'), {
                    text: <span className="font-mono font-semibold text-foreground">{confirmText}</span>,
                  })}
              </FieldLabel>
              <Input value={typed} onValueChange={setTyped} autoComplete="off" spellCheck={false} disabled={loading} />
            </Field>
          )}
          {error && <Alert tone="destructive" description={error} />}
          <AlertDialogFooter className="mt-1">
            <AlertDialogCancel disabled={loading}>{labels?.cancel ?? t('dangerZone.cancel')}</AlertDialogCancel>
            <Button type="submit" variant="destructive" disabled={!matches} loading={loading}>
              {confirmLabel}
            </Button>
          </AlertDialogFooter>
        </form>
      </AlertDialogContent>
    </AlertDialog>
  );
}

import { useI18n, Button, cn } from '@gntik-ai/ui';
import { useId, useState, type ReactNode } from 'react';
import { ConfirmDestructiveDialog, type ConfirmDestructiveDialogLabels } from './ConfirmDestructiveDialog';
import { dangerZoneActions, type DangerZoneAction } from './fixtures';

export type { DangerZoneAction } from './fixtures';

export interface DangerZoneLabels extends ConfirmDestructiveDialogLabels {
  title: string;
  description: string;
  confirmationTitle: (title: string) => string;
}

export interface DangerZoneProps {
  labels?: Partial<DangerZoneLabels>;
  title?: ReactNode;
  description?: ReactNode;
  actions?: DangerZoneAction[];
  /** Called after the user confirms an action. A returned promise shows a loading state. */
  onConfirm?: (actionId: string) => void | Promise<void>;
  headingLevel?: 'h2' | 'h3' | 'h4';
  className?: string;
}

/**
 * Bordered destructive section. Each action opens a confirmation dialog; actions with
 * `confirmText` require typing it (e.g. the project name) before the confirm button enables.
 */
export function DangerZone({
  labels,
  title: titleProp,
  description: descriptionProp,
  actions = dangerZoneActions,
  onConfirm,
  headingLevel: Heading = 'h2',
  className,
}: DangerZoneProps) {
  const { t } = useI18n();
  const title = titleProp === undefined ? (labels?.title ?? t('dangerZone.title')) : titleProp;
  const description =
    descriptionProp === undefined ? (labels?.description ?? t('dangerZone.description')) : descriptionProp;
  const id = useId();
  const [pending, setPending] = useState<DangerZoneAction | null>(null);
  const [open, setOpen] = useState(false);

  return (
    <section
      aria-labelledby={`${id}-title`}
      className={cn('rounded-lg border border-destructive/35 bg-card shadow-sm', className)}
    >
      <div className="border-b border-destructive/20 px-6 py-4">
        <Heading id={`${id}-title`} className="text-[15px] font-semibold tracking-tight text-destructive-text">
          {title}
        </Heading>
        {description != null && (
          <p className="mt-1 text-[13px] leading-6 text-pretty text-muted-foreground">{description}</p>
        )}
      </div>
      <ul className="divide-y divide-border">
        {actions.map((action) => (
          <li
            key={action.id}
            className="flex flex-col gap-3 px-6 py-4 sm:flex-row sm:items-center sm:justify-between sm:gap-6"
          >
            <div className="min-w-0">
              <div className="text-[13.5px] font-semibold text-foreground">{action.title}</div>
              <p className="mt-0.5 max-w-xl text-[12.5px] leading-5 text-pretty text-muted-foreground">
                {action.description}
              </p>
            </div>
            <Button
              variant={action.destructive === false ? 'secondary' : 'destructive'}
              className="shrink-0 self-start sm:self-auto"
              onClick={() => {
                setPending(action);
                setOpen(true);
              }}
            >
              {action.actionLabel}
            </Button>
          </li>
        ))}
      </ul>
      {pending && (
        <ConfirmDestructiveDialog
          key={pending.id}
          open={open}
          onOpenChange={setOpen}
          labels={labels}
          title={
            labels?.confirmationTitle?.(pending.title) ?? t('dangerZone.confirmationTitle', { title: pending.title })
          }
          description={pending.description}
          confirmText={pending.confirmText}
          confirmLabel={pending.actionLabel}
          onConfirm={() => onConfirm?.(pending.id)}
        />
      )}
    </section>
  );
}

export interface DangerZoneAction {
  id: string;
  title: string;
  description: string;
  /** Label of the row button and of the confirming button. */
  actionLabel: string;
  /** Text the user must type to confirm (e.g. the resource name). Omit for a plain confirmation. */
  confirmText?: string;
  /** Use the destructive button style in the row (default true); `false` renders a secondary button. */
  destructive?: boolean;
}

export const dangerZoneActions: DangerZoneAction[] = [
  {
    id: 'transfer',
    title: 'Transfer project',
    description: 'Move this project and its deployments to another workspace you administer.',
    actionLabel: 'Transfer',
    destructive: false,
  },
  {
    id: 'archive',
    title: 'Archive project',
    description: 'Stops every deployment and makes the project read-only. You can restore it later.',
    actionLabel: 'Archive',
    confirmText: 'billing-dashboard',
  },
  {
    id: 'delete',
    title: 'Delete project',
    description:
      'Permanently deletes billing-dashboard, its deployments, secrets and audit log. This cannot be undone.',
    actionLabel: 'Delete project',
    confirmText: 'billing-dashboard',
  },
];

import { Fragment, type ReactNode } from 'react';

/** Keep caller-owned rich content in place while the catalog controls sentence order. */
export function translatedContent(message: string, values: Record<string, ReactNode>): ReactNode {
  return message
    .split(/(\{\w+\})/)
    .map((part, index) => (
      <Fragment key={index}>
        {part.startsWith('{') && part.endsWith('}') ? (values[part.slice(1, -1)] ?? part) : part}
      </Fragment>
    ));
}
